"""Compiled skill primitives: ``Skill``, ``ProseBlock``, ``OrderedBlock``.

The catalog stores :class:`Skill` with a document-ordered ``body``.
"""

from __future__ import annotations

from collections.abc import Sequence
from typing import Annotated, Any, Literal, Union

from pydantic import BaseModel, ConfigDict, Field

from rasa.mantle.memory.schema import SkillMemoryContract
from rasa.mantle.skills.conditions import Condition, GatedTool, VerbatimTrigger
from rasa.mantle.skills.logic import CompleteWhenSpec
from rasa.mantle.skills.prose_scoping import ProseSegment
from rasa.mantle.skills.steps import Step

ORDERED_BLOCK_TARGET_ID_SEPARATOR = "__"
"""Separator between skill id and bare block id in a compiled ``target_id``."""


class ProseBlock(BaseModel):
    """A run of prose paragraphs in a skill body (no id, no step cursor)."""

    model_config = ConfigDict(frozen=True)

    type: Literal["prose"] = "prose"
    segments: list[ProseSegment] = Field(default_factory=list)


class OrderedBlock(BaseModel):
    """An ordered block in a skill body with steps and per-block tool gates."""

    model_config = ConfigDict(frozen=True)

    type: Literal["ordered_block"] = "ordered_block"
    block_id: str
    steps: list[Step] = Field(default_factory=list)
    tools: list[GatedTool] = Field(default_factory=list)
    complete_when: Condition | None = None
    routable: bool = True
    """Engine-owned: ``False`` on hybrid prose+blocks skills, ``True`` on
    block-only skills (same semantics as compiled ordered-block ``routable``).
    """

    def model_post_init(self, __context: Any) -> None:
        """Auto-link steps whose ``next`` is ``None`` to the following step."""
        from rasa.mantle.skills.steps import EndStep, LinkStep
        from rasa.shared.core.flows.steps.constants import END_STEP

        updated: list[Step] = []
        for i, step in enumerate(self.steps):
            if isinstance(step, (EndStep, LinkStep)):
                updated.append(step)
                continue
            if getattr(step, "next", None) is not None:
                updated.append(step)
                continue
            if i + 1 < len(self.steps):
                implicit_next = self.steps[i + 1].id
            else:
                implicit_next = END_STEP
            updated.append(step.model_copy(update={"next": implicit_next}))
        object.__setattr__(self, "steps", updated)

    def step_by_id(self, step_id: str) -> Step | None:
        """Return the step with the given ID, or ``None`` if not found."""
        return find_step_by_id(self.steps, step_id)


SkillBodyBlock = Annotated[
    Union[ProseBlock, OrderedBlock],
    Field(discriminator="type"),
]


class Skill(BaseModel):
    """Compiled skill with a document-ordered ``body``."""

    model_config = ConfigDict(frozen=True)

    id: str
    name: str | None = None
    description: str | None = None
    body: list[SkillBodyBlock] = Field(default_factory=list)
    tools: list[GatedTool] = Field(default_factory=list)
    import_tool_names: frozenset[str] = Field(default_factory=frozenset)
    tool_constraint_names: frozenset[str] = Field(default_factory=frozenset)
    verbatim_triggers: list[VerbatimTrigger] = Field(default_factory=list)
    complete_when: CompleteWhenSpec | None = None
    knowledge_answering_instructions: str | None = None
    memory: SkillMemoryContract = Field(default_factory=SkillMemoryContract)
    is_default: bool = False
    engine_managed: bool = False
    disabled: bool = False
    always_include_in_prompt: bool = False
    """If true, this skill's startable targets stay in the routing catalogue."""
    hidden: bool = False
    """When True, omit from global routing.

    Deterministic ``call`` / ``link`` and ``resolve_with`` may still start it.
    """
    precondition: str | None = None
    """Semantic precondition name; project binds it in ``agent.yml``."""
    referenced_skills: list[str] = Field(default_factory=list)
    referenced_blocks: list[str] = Field(default_factory=list)


def format_skill_target_id(skill_id: str) -> str:
    """Return the compiled ``target_id`` for a skill's prose entry (``skill_id``)."""
    return skill_id


def format_ordered_block_target_id(skill_id: str, block_id: str) -> str:
    """Return ``{skill_id}__{block_id}`` for an ordered-block activate address."""
    return f"{skill_id}{ORDERED_BLOCK_TARGET_ID_SEPARATOR}{block_id}"


def find_step_by_id(steps: Sequence[Step], step_id: str) -> Step | None:
    """Return the first step whose ``id`` matches *step_id*, or ``None``."""
    for step in steps:
        if step.id == step_id:
            return step
    return None
